// Des: Unit tests for chain pause and resume
// Flo: pause > tick > gate holds, clocks shift > resume > chain goes on
// I/O: fake chain, fake tick clock, done ring > pass or fail
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const supe = @import("tasksuper"); const tick = @import("tk-task-tick.zig");
const base = @import("tk-tick-base.zig"); const tszz = std.testing; const Sche = tick.Sche; const CF = tick.CF;
fn chaiFind(sche: *Sche) *Sche.ChaiRunz { for (&sche.chai) |*item| { if (item.used) return item; } unreachable; }
test "chain pause: only a running chain can pause, twice is refused, view shows it" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "boot", .sche = "boot", .ids = &.{"a"} } }; const none = [_]supe.Done{}; const nowz = time.localNow(); var duez: [4]Sche.Jobz = undefined; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); var arme = [_]armz.Armed{try armz.armTask(list[1])}; sche.arme = &arme; var coun: usize = 0; var fini_coun: usize = 0; try tszz.expectEqual(Sche.PausCode.none, sche.chaiPaus(iozz, "ch", true)); sche.chaiTick(iozz, nowz, 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expect(!sche.chaiView(iozz, "ch").?.paus); try tszz.expectEqual(Sche.PausCode.same, sche.chaiPaus(iozz, "ch", false)); try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", true)); try tszz.expect(sche.chaiView(iozz, "ch").?.paus); try tszz.expectEqual(Sche.PausCode.same, sche.chaiPaus(iozz, "ch", true)); try tszz.expectEqual(Sche.PausCode.none, sche.chaiPaus(iozz, "other", true)); try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", false)); try tszz.expect(!sche.chaiView(iozz, "ch").?.paus); }
test "chain pause: the next step does not start while paused, and the wait clock stops" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const plus_secs = std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), "[\"y\",\"m\",\"d\",\"h\",\"n\",[1]]", .{}) catch unreachable; var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "b", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "boot", .plus = plus_secs, .ids = &.{ "a", "b" } } }; var arme = [_]armz.Armed{try armz.armTask(list[2])}; sche.arme = &arme; var duez: [8]Sche.Jobz = undefined; var coun: usize = 0; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var fini_coun: usize = 0; const none = [_]supe.Done{}; const nowz = time.localNow(); sche.chaiTick(iozz, nowz, 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); var ring: supe.DoneRing = .{}; ring.push("a", true, 0); coun = 0; sche.chaiTick(iozz, nowz, 4_000, ring.item(), list[0..], &duez, &coun, &fini, &fini_coun); const chai = chaiFind(&sche); try tszz.expectEqual(@as(i64, 5_000), chai.next_msec); try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", true)); chai.paus_last = 4_000; sche.chaiTick(iozz, nowz, 9_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); try tszz.expectEqual(@as(i64, 10_000), chai.next_msec); sche.chaiTick(iozz, nowz, 60_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); try tszz.expectEqual(@as(i64, 61_000), chai.next_msec); chai.paus_last -= 3_000; const before = chai.next_msec; try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", false)); try tszz.expect(chai.next_msec >= before + 3_000); sche.chaiTick(iozz, nowz, 61_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); sche.chaiTick(iozz, nowz, chai.next_msec, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("b", duez[0].iden); }
test "chain pause: a step that finishes right at the pause is still counted, and the chain waits" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const zero = std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), "[[0],[0],[0],[0],[0],[0]]", .{}) catch unreachable; var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "b", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "boot", .plus = zero, .ids = &.{ "a", "b" } } }; var arme = [_]armz.Armed{try armz.armTask(list[2])}; sche.arme = &arme; var duez: [8]Sche.Jobz = undefined; var coun: usize = 0; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var fini_coun: usize = 0; const none = [_]supe.Done{}; const nowz = time.localNow(); sche.chaiTick(iozz, nowz, 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); coun = 0; try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", true)); const chai = chaiFind(&sche); chai.paus_last = 1_000; var ring: supe.DoneRing = .{}; ring.push("a", true, 0); sche.chaiTick(iozz, nowz, 2_000, ring.item(), list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(u32, 1), chai.ranz); try tszz.expectEqual(@as(usize, 0), coun); sche.chaiTick(iozz, nowz, 3_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", false)); sche.chaiTick(iozz, nowz, chai.next_msec + 1, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("b", duez[0].iden); }
test "chain pause: the step watchdog does not run out while paused" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x", .tmo = 10 }, .{ .id = "ch", .type = "boot", .ids = &.{"a"} } }; var arme = [_]armz.Armed{try armz.armTask(list[1])}; sche.arme = &arme; var duez: [4]Sche.Jobz = undefined; var coun: usize = 0; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var fini_coun: usize = 0; const none = [_]supe.Done{}; const nowz = time.localNow(); sche.chaiTick(iozz, nowz, 0, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); const chai = chaiFind(&sche); try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", true)); chai.paus_last = 0; const late: i64 = 10_000 + CF.chai_slac_msec + 5_000; sche.chaiTick(iozz, nowz, late, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(u32, 0), chai.ranz); try tszz.expectEqual(@as(usize, 0), fini_coun); try tszz.expect(sche.chaiView(iozz, "ch") != null); chai.paus_last = base.nowzMsec(iozz) - 7_000; const dead0 = chai.dead_msec; try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", false)); try tszz.expect(chai.dead_msec >= dead0 + 7_000); sche.chaiTick(iozz, nowz, chai.dead_msec - 1, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), fini_coun); sche.chaiTick(iozz, nowz, chai.dead_msec, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), fini_coun); }
test "chain pause: abort works on a paused chain, and the next run starts unpaused" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "boot", .sche = "boot", .ids = &.{"a"} } }; const none = [_]supe.Done{}; const nowz = time.localNow(); var duez: [4]Sche.Jobz = undefined; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); var arme = [_]armz.Armed{try armz.armTask(list[1])}; sche.arme = &arme; var coun: usize = 0; var fini_coun: usize = 0; sche.chaiTick(iozz, nowz, 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(Sche.PausCode.okzz, sche.chaiPaus(iozz, "ch", true)); try tszz.expect(sche.chaiAbor(iozz, "ch")); sche.chaiTick(iozz, nowz, 2_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), fini_coun); try tszz.expect(fini[0].abor); try tszz.expectEqual(Sche.PausCode.none, sche.chaiPaus(iozz, "ch", false)); _ = arme[0].requestHand(); coun = 0; sche.chaiTick(iozz, nowz, 3_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expect(!sche.chaiView(iozz, "ch").?.paus); }
